import { useEffect, useState } from 'react';
import { downloadAttendanceCsv, uploadEventBanner } from '../services/api';
import QrScanner from './QrScanner';

const emptyEvent = { title: '', description: '', date: '', time: '', location: '', event_type: 'offline', banner_image: '', capacity: 50, registration_deadline: '', is_free: true, price: 0, status: 'upcoming', waitlist_enabled: false, is_active: true };

function eventFormValues(event) {
  if (!event) return emptyEvent;
  const date = event.date ? new Date(event.date) : null;
  return { ...emptyEvent, ...event, date: date && !Number.isNaN(date.getTime()) ? date.toISOString().slice(0, 10) : event.date || '', time: event.time?.slice(0, 5) || (date ? date.toISOString().slice(11, 16) : ''), registration_deadline: event.registration_deadline ? new Date(event.registration_deadline).toISOString().slice(0, 16) : '' };
}

export default function AdminScreen({ events, people, onCreateEvent, onUpdateEvent, onDeleteEvent, onDeletePerson, onUpdatePerson, onCheckIn, attendance, analytics, onLoadAttendance }) {
  const [event, setEvent] = useState(emptyEvent);
  const [editingId, setEditingId] = useState(null);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState('');
  const [qrToken, setQrToken] = useState('');
  const [checkInResult, setCheckInResult] = useState(null);
  const [checkingIn, setCheckingIn] = useState(false);
  const [scannerOpen, setScannerOpen] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [eventQuery, setEventQuery] = useState('');
  const [peopleQuery, setPeopleQuery] = useState('');
  const filteredEvents = events.filter((item) => item.title.toLowerCase().includes(eventQuery.toLowerCase()));
  const filteredPeople = people.filter((person) => person.name.toLowerCase().includes(peopleQuery.toLowerCase()));

  useEffect(() => { if (editingId) setEvent(eventFormValues(events.find((item) => item.id === editingId))); }, [editingId, events]);
  function change(field, value) { setEvent((current) => ({ ...current, [field]: value })); }
  async function uploadBanner(file) { if (!file) return; setUploading(true); setUploadError(''); try { const result = await uploadEventBanner(file); change('banner_image', result.banner_image); } catch (error) { setUploadError(error.message || 'Banner upload failed. Check that the backend is running.'); } finally { setUploading(false); } }
  function cancelEdit() { setEditingId(null); setEvent(emptyEvent); setModalOpen(false); }
  function startCreate() { setEditingId(null); setEvent(emptyEvent); setModalOpen(true); }
  function startEdit(item) { setEditingId(item.id); setEvent(eventFormValues(item)); setModalOpen(true); }
  async function submit(eventObject) {
    eventObject.preventDefault(); setSaving(true);
    const payload = { ...event, capacity: Number(event.capacity), price: Number(event.price), is_free: Number(event.price) === 0, registration_deadline: event.registration_deadline ? new Date(event.registration_deadline).toISOString() : null };
    if (editingId) await onUpdateEvent(editingId, payload); else await onCreateEvent(payload);
    setSaving(false); cancelEdit();
  }
  async function checkInGuest(eventObject) {
    eventObject.preventDefault(); setCheckingIn(true); setCheckInResult(null);
    try { setCheckInResult(await onCheckIn(qrToken)); setQrToken(''); } catch (error) { setCheckInResult({ detail: error.message }); } finally { setCheckingIn(false); }
  }
  async function scan(value) { setScannerOpen(false); setQrToken(value); setCheckingIn(true); try { setCheckInResult(await onCheckIn(value)); onLoadAttendance(); } catch (error) { setCheckInResult({ detail: error.message }); } finally { setCheckingIn(false); } }
  async function exportAttendance() { setExporting(true); try { await downloadAttendanceCsv(); } catch (error) { setCheckInResult({ detail: error.message }); } finally { setExporting(false); } }

  return <>
    <div className="screen-heading"><div><span className="section-kicker">CONTROL ROOM</span><h2>Admin console</h2><p>Create, update, and manage community events and profiles.</p></div><div className="admin-heading-actions"><span className="admin-badge">{people.length} PEOPLE · {events.length} EVENTS</span><button type="button" className="primary-button" onClick={startCreate}>+ Create event</button></div></div>
    <form className="check-in-form" onSubmit={checkInGuest}><div><span className="section-kicker">DOOR DESK</span><h3>QR check-in</h3><p>Scan a member code or paste its URL to mark attendance.</p></div><div className="check-in-controls"><input aria-label="Registration QR URL" placeholder="Paste scanned QR URL" value={qrToken} onChange={(eventObject) => setQrToken(eventObject.target.value)} required /><button type="button" className="secondary-button" onClick={() => setScannerOpen(true)}>Use camera</button><button className="primary-button" disabled={checkingIn}>{checkingIn ? 'Checking...' : 'Mark attended'}</button></div>{scannerOpen && <QrScanner onScan={scan} />}{checkInResult && <p className={checkInResult.detail ? 'check-in-result error' : 'check-in-result'}>{checkInResult.detail || `${checkInResult.attendee?.name} checked in for ${checkInResult.event_title}.`}</p>}</form>
    {analytics && <div className="analytics-panel"><div><span className="section-kicker">SYSTEM OVERVIEW</span><h3>Dashboard analytics</h3></div><div className="analytics-grid"><div><small>Total users</small><strong>{analytics.users.total}</strong><span>{analytics.users.active} active</span></div><div><small>Events</small><strong>{analytics.events.total}</strong><span>{analytics.events.upcoming} upcoming</span></div><div><small>Participation</small><strong>{analytics.participation.registrations}</strong><span>{analytics.participation.attended} attended</span></div><div><small>User growth</small><strong>+{analytics.growth.users_last_30_days}</strong><span>Last 30 days</span></div></div></div>}
    <div className="attendance-panel"><div><span className="section-kicker">ATTENDANCE</span><h3>Checked-in guests</h3></div><button className="text-button" type="button" onClick={exportAttendance} disabled={exporting}>{exporting ? 'Preparing CSV...' : 'Export CSV ↗'}</button>{attendance.map((row) => <div className="admin-row" key={row.id}><span><strong>{row.attendee}</strong><small>{row.event_title} · {row.email}</small></span><small>{row.checked_in_at ? new Date(row.checked_in_at).toLocaleString() : ''}</small></div>)}</div>
    <div className="admin-layout"><div className="admin-stack"><div className="admin-events published-events"><div className="directory-toolbar"><h3>Published events</h3><label className="admin-search"><span>⌕</span><input value={eventQuery} onChange={(event) => setEventQuery(event.target.value)} placeholder="Search by event name" /></label></div>{filteredEvents.map((item) => <div className="admin-row" key={item.id}><span><strong>{item.title}</strong><small>{item.date} · {item.location}</small></span><div className="row-actions"><button className="edit-button" onClick={() => startEdit(item)}>Edit</button><button className="danger-icon" onClick={() => onDeleteEvent(item.id)} aria-label={`Delete ${item.title}`}>×</button></div></div>)}{!filteredEvents.length && <p className="empty-state">No events match this name.</p>}</div><div className="admin-events admin-people"><div className="directory-toolbar"><h3>People directory</h3><label className="admin-search"><span>⌕</span><input value={peopleQuery} onChange={(event) => setPeopleQuery(event.target.value)} placeholder="Search by name" /></label></div>{filteredPeople.map((item) => <div className="admin-row" key={item.id}><span className="admin-person-summary">{item.avatar_image ? <img src={item.avatar_image} alt="" /> : <span className="admin-person-initials">{item.name.slice(0, 2).toUpperCase()}</span>}<span><strong>{item.name}</strong><small>Class of {item.batch_year || '—'} · {item.current_company || 'No company'}</small></span></span><div className="row-actions"><select className="role-select" value={item.role || 'alumni'} onChange={(event) => onUpdatePerson(item.user_id, { role: event.target.value })}><option value="alumni">Alumni</option><option value="student">Student</option></select><button className="status-button" onClick={() => onUpdatePerson(item.user_id, { is_active: item.is_active === false })}>{item.is_active === false ? 'Enable' : 'Disable'}</button><button className="danger-icon" onClick={() => onDeletePerson(item.user_id || item.id)} aria-label={`Remove ${item.name}`}>×</button></div></div>)}{!filteredPeople.length && <p className="empty-state">No people match this name.</p>}</div></div></div>
    {modalOpen && <div className="modal-backdrop" role="presentation" onMouseDown={(eventObject) => { if (eventObject.target === eventObject.currentTarget) cancelEdit(); }}><form className="admin-form event-modal" onSubmit={submit}><div className="modal-heading"><div><span className="section-kicker">EVENT EDITOR</span><h3>{editingId ? 'Edit event' : 'Create an event'}</h3></div><button type="button" className="modal-close" onClick={cancelEdit} aria-label="Close event editor">×</button></div><label>Title<input required value={event.title} onChange={(e) => change('title', e.target.value)} /></label><label>Description<textarea required value={event.description} onChange={(e) => change('description', e.target.value)} /></label><div className="modal-two-col"><label>Date<input required type="date" value={event.date} onChange={(e) => change('date', e.target.value)} /></label><label>Start time<input required type="time" value={event.time} onChange={(e) => change('time', e.target.value)} /></label></div><label>Location or online link<input required value={event.location} onChange={(e) => change('location', e.target.value)} /></label><div className="modal-two-col"><label>Event type<select value={event.event_type} onChange={(e) => change('event_type', e.target.value)}><option value="offline">Offline</option><option value="online">Online</option><option value="hybrid">Hybrid</option></select></label><label>Capacity<input required type="number" min="1" value={event.capacity} onChange={(e) => change('capacity', e.target.value)} /></label></div><label>Banner image<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => uploadBanner(e.target.files?.[0])} />{uploading && <small className="upload-status">Uploading image...</small>}{uploadError && <small className="upload-status">{uploadError}</small>}{event.banner_image && <img className="banner-preview" src={event.banner_image} alt="Event banner preview" />}</label><div className="modal-two-col"><label>Registration deadline<input type="datetime-local" value={event.registration_deadline} onChange={(e) => change('registration_deadline', e.target.value)} /></label><label>Price<input type="number" min="0" step="0.01" value={event.price} onChange={(e) => change('price', e.target.value)} /></label></div><label>Status<select value={event.status} onChange={(e) => change('status', e.target.value)}><option value="upcoming">Upcoming</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label><div className="modal-checks"><label className="check-field"><input type="checkbox" checked={event.waitlist_enabled} onChange={(e) => change('waitlist_enabled', e.target.checked)} /> Enable waitlist</label><label className="check-field"><input type="checkbox" checked={event.is_active} onChange={(e) => change('is_active', e.target.checked)} /> Show event publicly</label></div><div className="form-footer"><button type="button" className="secondary-button" onClick={cancelEdit}>Cancel</button><button className="primary-button" disabled={saving || uploading}>{saving ? 'Saving...' : editingId ? 'Save changes ↗' : 'Publish event ↗'}</button></div></form></div>}
  </>;
}
