export default function EventCard({ event, registered, onRsvp, onDelete, onOpen, admin }) {
  const date = event.month ? event : (() => { const value = new Date(event.date); return { month: value.toLocaleDateString('en', { month: 'short' }).toUpperCase(), day: value.getDate() }; })();
  return <article className="event-card" onClick={() => onOpen?.(event)}><div className="date-tile"><span>{date.month}</span><strong>{date.day}</strong></div><div className="event-copy"><span className="tag">{event.event_type || event.type || 'COMMUNITY'}</span><h3>{event.title}</h3><p>{event.location || 'Location to be announced'}</p><div className="event-actions">{admin ? <button className="rsvp-button danger" onClick={(e) => { e.stopPropagation(); onDelete(event.id); }}>Delete</button> : <button className={registered ? 'rsvp-button registered' : 'rsvp-button'} onClick={(e) => { e.stopPropagation(); onRsvp(event); }}>{registered ? '✓ Going' : 'RSVP now'} <span>↗</span></button>}</div></div></article>;
}
